/*! Beownir headless kernel — embed Node/npm/dev-server execution in any web IDE.
 *
 * This file is generated by `node tools/build-embed.mjs` from the same sources
 * that ship inside beownir-standalone.html, so the embedded runtime cannot drift
 * from the IDE's. Do not edit the generated file; edit this template or the
 * runtime and rebuild.
 *
 * What you get: a virtual filesystem, a Node-compatible worker runtime, a
 * streamed npm installer and virtual HTTP servers (dev servers) on loopback —
 * all inside the visitor's browser. No server, no native binaries.
 *
 * The host page never evaluates anything: all execution happens in sandboxed
 * iframes with their own policies.
 *
 * What you do NOT get: raw TCP/UDP, native addons (.node), real ports. Those
 * throw named errors. A page cannot do them; nothing here pretends otherwise.
 *
 * Public surface: window.BeownirKernel (see EMBEDDING.md).
 */
(function attachBeownirKernel(global) {
  'use strict';
  if (global.BeownirKernel) return;

  /* ------------------------------------------------------------------ payload */
  /* The generator appends ASSETS below this block before the closing IIFE, so
   * the bundle is one file and needs no fetch() of its own parts. */
  const BUILD = __BEOWNIR_EMBED_BUILD__;

  const CONTAINER_ID = 'beownir-kernel-host';
  const SANDBOX_POLICY = "default-src 'none'; script-src 'unsafe-inline' 'unsafe-eval' 'wasm-unsafe-eval' blob:; worker-src blob:; connect-src https://registry.npmjs.org; img-src data: blob:; style-src 'unsafe-inline'; base-uri 'none'; object-src 'none'; form-action 'none'";

  const isPlainObject = value => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
  const toErrorMessage = error => String((error && error.message) || error || 'Unknown error').slice(0, 4000);

  /* Node-style path rules for the virtual filesystem. The kernel only accepts
   * /project and /tmp, so every helper normalises to those two roots. */
  function normalisePath(input, { relativeTo = '/project' } = {}) {
    if (typeof input !== 'string' || !input.trim()) throw new TypeError('A path string is required.');
    let path = input.trim().replace(/\\/g, '/');
    if (!path.startsWith('/')) path = (relativeTo.replace(/\/$/, '') || '') + '/' + path;
    const out = [];
    for (const part of path.split('/')) {
      if (!part || part === '.') continue;
      if (part === '..') { out.pop(); continue; }
      out.push(part);
    }
    return '/' + out.join('/');
  }

  function assertWritablePath(path) {
    if (path !== '/project' && path !== '/tmp' && !path.startsWith('/project/') && !path.startsWith('/tmp/')) {
      const error = new Error('Only /project and /tmp are writable in the virtual filesystem: ' + path);
      error.code = 'EPERM';
      throw error;
    }
    return path;
  }

  const parentOf = path => { const index = path.lastIndexOf('/'); return index <= 0 ? '/' : path.slice(0, index); };

  /** Builds the {path: entry} map the kernel's init/setfiles messages expect. */
  function toFileMap(files) {
    if (files === undefined || files === null) return {};
    if (typeof files !== 'object') throw new TypeError('files must be an object mapping absolute paths to strings or {content} records.');
    const map = {};
    for (const [rawPath, value] of Object.entries(files)) {
      const path = assertWritablePath(normalisePath(rawPath));
      if (value === null) { map[path] = null; continue; }
      if (typeof value === 'string') { map[path] = { c: value }; continue; }
      if (isPlainObject(value)) {
        if (value.directory === true || value.d === true) { map[path] = { d: true }; continue; }
        if (typeof value.content === 'string') { map[path] = { c: value.content }; continue; }
        if (typeof value.c === 'string') { map[path] = { c: value.c }; continue; }
      }
      throw new TypeError('Unsupported file record for ' + path + ': expected a string, {content} or {directory: true}.');
    }
    return withParents(map);
  }

  /* The kernel needs intermediate directories to exist before a file lands in
   * them, otherwise writeFileSync fails with ENOENT. A host that only knows leaf
   * files should not have to spell out every directory, so add them here. */
  function withParents(map) {
    const result = { ...map };
    for (const path of Object.keys(map)) {
      let parent = parentOf(path);
      while (parent !== '/' && parent !== '/project' && parent !== '/tmp') {
        if (!(parent in result)) result[parent] = { d: true };
        parent = parentOf(parent);
      }
    }
    result['/project'] = result['/project'] || { d: true };
    result['/tmp'] = result['/tmp'] || { d: true };
    return result;
  }

  class BeownirKernel {
    /**
     * Options:
     *   files        { '/project/app.js': 'console.log(1)' }  (optional)
     *   container    Element or selector to host the hidden frame (default: <body>)
     *   limits       { bytes, perFile, entries } overrides for the workspace budget
     *   autostart    boot immediately (default true)
     */
    constructor(options = {}) {
      this._options = options;
      this._files = toFileMap(options.files);
      this._listeners = new Map();
      this._ports = new Set();
      this._commands = new Map();
      this._pendingHttp = new Map();
      this._commandSeq = 0;
      this._state = 'idle';
      this._buffer = { stdout: '' };
      this._destroyed = false;
      this._frame = null;
      this._channel = null;
      this._ready = this._deferred();
      this._booted = this._deferred();
      if (options.autostart !== false) this.start();
    }

    _deferred() {
      const deferred = {};
      deferred.promise = new Promise((resolve, reject) => { deferred.resolve = resolve; deferred.reject = reject; });
      deferred.promise.catch(() => {});
      return deferred;
    }

    /* ------------------------------------------------------------- lifecycle */

    /** Boots the kernel. Returns a promise resolved when the runtime is ready. */
    start() {
      if (this._destroyed) return Promise.reject(new Error('This kernel instance was destroyed.'));
      if (this._frame) return this._booted.promise;
      this._setState('booting');
      const container = this._resolveContainer();
      const frame = document.createElement('iframe');
      frame.id = CONTAINER_ID;
      frame.title = 'Beownir kernel';
      /* allow-scripts only: the kernel runs in an opaque origin, so project code
       * cannot reach this page's storage, cookies or DOM. */
      frame.setAttribute('sandbox', 'allow-scripts');
      frame.setAttribute('referrerpolicy', 'no-referrer');
      frame.setAttribute('aria-hidden', 'true');
      frame.style.cssText = 'position:absolute;width:0;height:0;border:0;visibility:hidden';
      const policy = "<meta http-equiv=\"Content-Security-Policy\" content=\"" + SANDBOX_POLICY + "\">";
      frame.srcdoc = '<!doctype html><meta charset="utf-8">' + policy + '<script>' + BUILD.kernel.replace(/<\/script/gi, '<\\/script') + '<\/script>';
      const bootTimer = setTimeout(() => {
        this._fail(new Error('The kernel frame did not report back within 20 s. Sandboxed iframes or blob workers may be blocked on this page.'));
      }, 20000);
      frame.addEventListener('load', () => {
        if (this._destroyed) return;
        const pair = new MessageChannel();
        this._channel = pair.port1;
        this._channel.onmessage = event => this._receive(event.data);
        this._channel.start();
        frame.contentWindow.postMessage(
          { type: 'beownir-runtime', source: BUILD.runtime, limits: this._options.limits || {} },
          '*',
          [pair.port2],
        );
        this._bootTimer = bootTimer;
      }, { once: true });
      container.appendChild(frame);
      this._frame = frame;
      return this._booted.promise;
    }

    _resolveContainer() {
      const target = this._options.container;
      if (target && typeof target === 'object' && target.appendChild) return target;
      if (typeof target === 'string') {
        const found = document.querySelector(target);
        if (!found) throw new Error('container not found: ' + target);
        return found;
      }
      return document.body || document.documentElement;
    }

    /** Stops every process, server and timer, and removes the frame. */
    destroy() {
      this._destroyed = true;
      this._setState('destroyed');
      try { this._channel?.postMessage({ type: 'terminate' }); } catch {}
      try { this._channel?.close(); } catch {}
      try { this._frame?.remove(); } catch {}
      for (const pending of this._commands.values()) pending.reject(new Error('The kernel was destroyed.'));
      this._commands.clear();
      for (const pending of this._pendingHttp.values()) pending.reject(new Error('The kernel was destroyed.'));
      this._pendingHttp.clear();
      this._ports.clear();
      this._ready.reject(new Error('The kernel was destroyed.'));
      this._booted.reject(new Error('The kernel was destroyed.'));
      this._frame = null;
      this._channel = null;
      this._emit('state', { state: 'destroyed' });
    }

    get state() { return this._state; }
    get ready() { return this._state === 'ready'; }
    get ports() { return [...this._ports].sort((a, b) => a - b); }
    get files() { return { ...this._files }; }

    /** Resolves when the runtime can accept commands. */
    whenReady() { return this._ready.promise; }

    /* ---------------------------------------------------------------- events */

    /** on('stdout'|'stderr'|'server'|'exit'|'files'|'state'|'error', handler) */
    on(type, handler) {
      if (typeof handler !== 'function') throw new TypeError('A handler function is required.');
      if (!this._listeners.has(type)) this._listeners.set(type, new Set());
      this._listeners.get(type).add(handler);
      return () => this.off(type, handler);
    }

    off(type, handler) { this._listeners.get(type)?.delete(handler); return this; }

    _emit(type, payload) {
      const handlers = this._listeners.get(type);
      if (!handlers) return;
      for (const handler of handlers) {
        try { handler(payload); } catch (error) { console.error('[beownir-kernel] ' + type + ' handler threw', error); }
      }
    }

    _setState(state) {
      if (this._state === state) return;
      this._state = state;
      this._emit('state', { state });
    }

    _fail(error) {
      this._setState('failed');
      const wrapped = error instanceof Error ? error : new Error(String(error));
      this._emit('error', { error: wrapped });
      this._booted.reject(wrapped);
      this._ready.reject(wrapped);
    }

    /* ------------------------------------------------------------ filesystem */

    /** Replaces the whole virtual filesystem. Paths outside /project and /tmp are rejected. */
    async setFiles(files) {
      const map = toFileMap(files);
      await this._post({ type: 'setfiles', files: map, versions: {} });
      this._files = map;
      this._emit('files', { files: { ...map } });
      return { files: { ...map } };
    }

    /** Writes one file, creating parent directories. */
    async writeFile(path, content) {
      if (typeof content !== 'string') throw new TypeError('writeFile requires a string. Use writeFileBytes for binary content.');
      const target = assertWritablePath(normalisePath(path));
      const map = withParents({ [target]: { c: content } });
      await this._post({ type: 'setfiles', files: map, versions: {} });
      Object.assign(this._files, map);
      this._emit('files', { files: { [target]: map[target] } });
      return { path: target };
    }

    /** Writes binary content (base64 or Uint8Array) as a latin1 string record. */
    async writeFileBytes(path, bytes) {
      const buffer = bytes instanceof Uint8Array ? bytes : Uint8Array.from(atob(String(bytes)), character => character.charCodeAt(0));
      let text = '';
      for (let index = 0; index < buffer.length; index += 0x8000) text += String.fromCharCode.apply(null, buffer.subarray(index, index + 0x8000));
      return this.writeFile(path, text);
    }

    /** Current content of a file from the client-side mirror, or null. */
    readFile(path) {
      const entry = this._files[normalisePath(path)];
      if (!entry || entry.d) return null;
      return entry.c ?? '';
    }

    /** Whether a path currently exists in the client-side mirror. */
    exists(path) { return Boolean(this._files[normalisePath(path)]); }

    /** Removes one file or directory entry. */
    async removeFile(path) {
      const target = assertWritablePath(normalisePath(path));
      if (target === '/project' || target === '/tmp') {
        const error = new Error('The workspace and temporary roots cannot be removed: ' + target);
        error.code = 'EPERM';
        throw error;
      }
      await this._post({ type: 'setfiles', files: { [target]: null }, versions: {} });
      delete this._files[target];
      this._emit('files', { files: { [target]: null } });
      return { path: target };
    }

    /* -------------------------------------------------------------- commands */

    /**
     * Runs a shell command (`node app.js`, `npm install vite`, `npm run build`,
     * `npx serve`, …). Resolves with the exit code and the captured output.
     */
    async run(command, { timeoutMs = 0, onData } = {}) {
      if (typeof command !== 'string' || !command.trim()) throw new TypeError('run() needs a command string.');
      await this._ready.promise;
      const id = 'cmd-' + (++this._commandSeq);
      const pending = this._deferred();
      const timer = timeoutMs > 0 ? setTimeout(() => {
        if (!this._commands.has(id)) return;
        this._commands.delete(id);
        pending.reject(new Error('Command timed out after ' + timeoutMs + ' ms: ' + command));
      }, timeoutMs) : null;
      this._commands.set(id, { ...pending, stdout: '', stderr: '', timer, onData });
      /* The shell worker takes `line` and queues commands internally. */
      this._channel.postMessage({ type: 'cmd', id, line: command });
      return pending.promise;
    }

    /** Sends stdin to the running command (used by prompts and REPLs). */
    sendInput(data) {
      if (typeof data !== 'string') throw new TypeError('sendInput requires a string.');
      this._channel?.postMessage({ type: 'stdin', data });
    }

    /** Kills a process by pid, or everything with `all: true`. */
    async kill(pid, signal = 'SIGTERM') {
      await this._ready.promise;
      this._channel.postMessage({ type: 'kill-process', pid, signal, tree: true });
      return true;
    }

    /* ------------------------------------------------------------ virtual HTTP */

    /**
     * Requests a URL from a server running inside the kernel.
     * `http('http://localhost:5173/src/main.js')` → { status, headers, body, bytes }
     */
    async http(input, init = {}) {
      await this._ready.promise;
      const url = new URL(String(input), 'http://localhost');
      const port = Number(url.port || (url.protocol === 'https:' ? 443 : 80));
      const method = String(init.method || 'GET').toUpperCase();
      const headers = init.headers ? Object.fromEntries(new Headers(init.headers)) : {};
      const body = init.body ? await new Response(init.body).arrayBuffer() : null;
      const id = 'http-' + (++this._commandSeq);
      const pending = this._deferred();
      this._pendingHttp.set(id, pending);
      this._channel.postMessage({ type: 'http', id, port, url: url.pathname + url.search, method, headers, body: body ? new Uint8Array(body) : null });
      const response = await pending.promise;
      return {
        status: response.status,
        headers: response.headers || {},
        bytes: response.body || new Uint8Array(),
        body: new TextDecoder().decode(response.body || new Uint8Array()),
      };
    }

    /** Convenience: parsed JSON from the virtual server. */
    async httpJson(input, init) {
      const response = await this.http(input, init);
      if (response.status >= 400) throw new Error('HTTP ' + response.status + ' from ' + String(input));
      return JSON.parse(response.body);
    }

    /**
     * Polls a virtual URL until it answers (a dev server is up) or the deadline
     * passes. Resolves with the final response.
     */
    async waitForServer(port, { path = '/', timeoutMs = 30000, intervalMs = 250 } = {}) {
      const deadline = Date.now() + timeoutMs;
      let lastError = null;
      while (Date.now() < deadline) {
        try {
          const response = await this.http('http://localhost:' + port + path);
          if (response.status < 500) return response;
        } catch (error) { lastError = error; }
        await new Promise(resolve => setTimeout(resolve, intervalMs));
      }
      throw new Error('Nothing answered on virtual port ' + port + ' within ' + timeoutMs + ' ms' + (lastError ? ': ' + lastError.message : ''));
    }

    /* -------------------------------------------------------------- internal */

    /** Decompresses the embedded esbuild wasm (gzipped base64, as the IDE ships it). */
    async _gunzipAssets() {
      const compressed = decode64(BUILD.esbuildWasm);
      let wasm = null;
      if (typeof DecompressionStream === 'function') {
        try { wasm = await gunzipStream(compressed); } catch { wasm = null; }
      }
      if (!wasm) {
        /* Engines without DecompressionStream (Firefox < 113, Safari < 16.4):
         * gunzip inside a sandboxed iframe running the bundled pako. The
         * iframe carries its own CSP, so a host page that forbids eval still
         * boots. */
        wasm = await gunzipInSandbox(compressed);
      }
      /* Transfer a copy so a view on a larger buffer can never leak extra bytes. */
      return { wasm: wasm.slice(), browser: decode64Text(BUILD.esbuildBrowser) };
    }

    _post(message) {
      if (!this._channel) return Promise.reject(new Error('The kernel is not running. Call start() first.'));
      this._channel.postMessage(message);
      return Promise.resolve();
    }

    _receive(message) {
      if (!message || typeof message !== 'object') return;
      switch (message.type) {
        case 'connected': {
          const channel = this._channel;
          /* The wasm asset ships gzipped (as in the IDE); decompress it here
           * before handing it to the kernel. This is async, and the kernel
           * simply waits for the init message. */
          this._gunzipAssets().then(({ wasm, browser }) => {
            if (this._destroyed || this._channel !== channel) return;
            const init = {
              type: 'init',
              files: withParents(this._files),
              versions: {},
              limits: this._options.limits || {},
              embeddedEsbuildWasm: wasm,
              embeddedEsbuildBrowser: browser,
              embeddedPako: BUILD.pako,
            };
            channel.postMessage(init, [wasm.buffer]);
          }).catch(error => this._fail(error));
          break;
        }
        case 'ready': {
          clearTimeout(this._bootTimer);
          this._setState('ready');
          this._booted.resolve(this);
          this._ready.resolve(this);
          break;
        }
        case 'stdout':
        case 'stderr': {
          const text = String(message.data ?? '');
          this._emit(message.type, { data: text });
          /* The kernel relays output without a command id; commands run one at
           * a time in the shell worker, so attribute to the oldest pending. */
          const owner = this._commands.values().next().value;
          if (owner) {
            owner[message.type] += text;
            try { owner.onData?.({ stream: message.type, data: text }); } catch (error) { console.error(error); }
          }
          break;
        }
        case 'question':
          this._emit('question', { data: String(message.data ?? ''), pid: message.pid });
          break;
        case 'questionend':
          this._emit('questionend', {});
          break;
        case 'listen':
          if (Number.isInteger(message.port)) {
            this._ports.add(message.port);
            this._emit('server', { port: message.port, listening: true });
          }
          break;
        case 'close':
          if (Number.isInteger(message.port)) {
            this._ports.delete(message.port);
            this._emit('server', { port: message.port, listening: false });
          }
          break;
        case 'done': {
          const pending = this._commands.get(message.id);
          if (!pending) break;
          clearTimeout(pending.timer);
          this._commands.delete(message.id);
          this._emit('exit', { id: message.id, code: Number(message.code) || 0, stdout: pending.stdout, stderr: pending.stderr });
          pending.resolve({ code: Number(message.code) || 0, stdout: pending.stdout, stderr: pending.stderr, cwd: message.cwd });
          break;
        }
        case 'httpres': {
          const pending = this._pendingHttp.get(message.id);
          if (!pending) break;
          this._pendingHttp.delete(message.id);
          pending.resolve({ status: message.status, headers: message.headers, body: message.body });
          break;
        }
        case 'fssync':
          if (isPlainObject(message.files)) {
            for (const [path, entry] of Object.entries(message.files)) {
              if (entry === null) delete this._files[path]; else this._files[path] = entry;
            }
            this._emit('files', { files: message.files, versions: message.versions || {} });
          }
          break;
        case 'fatal':
          this._fail(new Error(message.message || 'The kernel stopped unexpectedly.'));
          break;
        case 'kernel-stopped':
          if (!this._destroyed) this._setState('stopped');
          break;
        default:
          /* kernel-processes, pkgprogress, notice, clear, open … surface as
           * generic events so a host can render them without a client update. */
          this._emit(message.type, message);
      }
    }
  }

  /* base64 → bytes without depending on pako. */
  function decode64(text) {
    const binary = atob(String(text || '').replace(/\s+/g, ''));
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index++) bytes[index] = binary.charCodeAt(index);
    return bytes;
  }
  function decode64Text(text) { return new TextDecoder().decode(decode64(text)); }

  /* Runs the bundled pako copy inside a throwaway sandboxed iframe and gunzips
   * `bytes` there. The frame's own CSP allows eval; the host page's does not
   * need to, because this code never evaluates anything in the page. */
  function gunzipInSandbox(bytes) {
    return new Promise((resolve, reject) => {
      const host = document.body || document.documentElement;
      if (!host) { reject(new Error('The document has no body to host the decompressor in.')); return; }
      const frame = document.createElement('iframe');
      frame.title = 'Beownir asset decompressor';
      frame.setAttribute('sandbox', 'allow-scripts');
      frame.setAttribute('referrerpolicy', 'no-referrer');
      frame.setAttribute('aria-hidden', 'true');
      frame.style.cssText = 'position:absolute;width:0;height:0;border:0;visibility:hidden';
      const policy = "<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; script-src 'unsafe-inline' 'unsafe-eval'; base-uri 'none'; object-src 'none'; form-action 'none'\">";
      const bridge = "window.onmessage=function(event){var port=event.ports[0];if(!port)return;port.onmessage=function(message){try{var out=pako.ungzip(message.data);port.postMessage(out,[out.buffer]);}catch(failure){port.postMessage({error:String(failure&&failure.message||failure)});}};port.start();};";
      frame.srcdoc = '<!doctype html><meta charset="utf-8">' + policy + '<script>' + BUILD.pako.replace(/<\/script/gi, '<\\/script') + '<\/script><script>' + bridge + '<\/script>';
      const timer = setTimeout(() => { cleanup(); reject(new Error('The bundled decompressor did not answer within 30 s.')); }, 30000);
      const cleanup = () => { clearTimeout(timer); try { frame.remove(); } catch {} };
      frame.addEventListener('load', () => {
        const pair = new MessageChannel();
        pair.port1.onmessage = event => {
          const data = event.data;
          cleanup();
          if (data && data.error) reject(new Error('The bundled decompressor failed: ' + data.error));
          else if (data instanceof Uint8Array && data.length) resolve(data);
          else reject(new Error('The bundled decompressor returned no bytes.'));
        };
        pair.port1.start();
        frame.contentWindow.postMessage('beownir-gunzip', '*', [pair.port2]);
        pair.port1.postMessage(bytes);
      }, { once: true });
      host.appendChild(frame);
    });
  }

  async function gunzipStream(bytes) {
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
    const reader = stream.getReader();
    const chunks = [];
    let total = 0;
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
      total += value.length;
    }
    const out = new Uint8Array(total);
    let offset = 0;
    for (const chunk of chunks) { out.set(chunk, offset); offset += chunk.length; }
    return out;
  }

  const api = {
    version: BUILD.version,
    create: options => new BeownirKernel(options),
    BeownirKernel,
    normalisePath,
    /** Feature probe for a host that wants to warn before booting. */
    capabilities: () => ({
      worker: typeof Worker === 'function',
      blob: typeof Blob === 'function' && typeof URL.createObjectURL === 'function',
      iframe: typeof HTMLIFrameElement === 'function',
      webassembly: typeof WebAssembly === 'object',
      serviceWorker: typeof navigator !== 'undefined' && 'serviceWorker' in navigator,
      crossOriginIsolated: typeof crossOriginIsolated !== 'undefined' && Boolean(crossOriginIsolated),
    }),
  };

  global.BeownirKernel = Object.freeze(api);
})(typeof window !== 'undefined' ? window : globalThis);
